    p=acts[g]; m=prev
    for _ in range(3):
        sel=np.linalg.norm(p-m,axis=1)<0.45
        if sel.sum()<3: return m,0
        m=p[sel].mean(0)
    return m,sel.sum()
g0=0.24; cen[g0],_=step(np.array([1.10,2.17]),g0)
for seq in [grid[grid>g0],grid[grid<g0][::-1]]:
    prev=cen[g0]
    for g in seq:
        cen[g],n=step(prev,g); prev=cen[g]
        if n==0: print('lost at',g)
gs=np.array(sorted(cen)); C=np.array([cen[g] for g in gs])
for g,cc in zip(gs[::3],C[::3]): print(g,np.round(cc,2), (np.linalg.norm(acts[g]-cc,axis=1)<0.4).mean().round(3))
np.save('track.npy',np.c_[gs,C].astype(np.float32))
D=np.load('data.npz'); a0=D['a']; cn=D['c']
ctr=np.stack([np.interp(cn,gs,C[:,0]),np.interp(cn,gs,C[:,1])],1)
y2=np.linalg.norm(a0-ctr,axis=1)<0.4
print('label share by decile',[round(y2[(cn>=l)&(cn<l+0.1)].mean(),3) for l in np.arange(0,1,0.1)], 'old', D['y'].sum(), 'new', y2.sum(), 'overlap', (y2&D['y']).sum())
np.save('y2.npy',y2)
